 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    axes = []
    # Each solid 3x3 colored square emits a horizontal and vertical line
    # through its center. Locate the squares from their top-left cells.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[rr][cc] == color
                   for rr in range(r, r + 3)
                   for cc in range(c, c + 3)):
                if (r == 0 or c == 0 or grid[r-1][c] != color
                        or grid[r][c-1] != color):
                    axes.append((r + 1, c + 1, color))
    # Draw all axes, with a zero at every crossing of perpendicular axes.
    horizontals = {}
    verticals = {}
    for r, c, color in axes:
        horizontals[r] = color
        verticals[c] = color
    for r, color in horizontals.items():
        for c in range(w):
            out[r][c] = color
    for c, color in verticals.items():
        for r in range(h):
            out[r][c] = color
    for r in horizontals:
        for c in verticals:
            out[r][c] = 0
    return out
